int unsetenv ( const char * name ) { size_t len ; char * * ep ; if ( name == NULL || * name == '\0' || strchr ( name , '=' ) != NULL ) { return - 1 ; } len = strlen ( name ) ; LOCK ; ep = __environ ; while ( * ep != NULL ) { if ( ! strncmp ( * ep , name , len ) && ( * ep ) [ len ] == '=' ) { char * * dp = ep ; { dp [ 0 ] = dp [ 1 ] ; } * dp ++ ; } else { ++ ep ; } } UNLOCK ; return 0 ; } 